// ABO Admin · Content page editors (About Us / Contact Us).
//
// Front-end only, static data. The dataset is generated by the
// matching Blade view (resources/views/admin/pages/about.blade.php
// or resources/views/admin/pages/contact.blade.php) and serialised
// into a single <script type="application/json"> tag. This script
// hydrates the editor from that one dataset.
//
// No fetch / XHR / WebSockets. No localStorage. Save buttons are
// visual only and just show "Saved (demo)" in a toast.
//
// The two pages are different enough (repeating content blocks
// vs. working-hours + messages inbox) that the script decides
// which one to wire by looking at which dataset is present:
//
//   #abo-admin-content-about-data   → About Us editor
//   #abo-admin-content-contact-data → Contact Us editor
//
// All the shared bits (lang switch, status toggle, SEO counter,
// toast, dirty dot, modal + Escape close) live in
// `initShared()` and run regardless of which page is active.

/* eslint-disable no-console */

(function () {
    'use strict';

    const $  = (sel, root) => (root || document).querySelector(sel);
    const $$ = (sel, root) => Array.from((root || document).querySelectorAll(sel));

    const root = document.querySelector('.abo-admin-page') || document.body;

    function readJSON(id, fallback) {
        const el = document.getElementById(id);
        try { return JSON.parse(el ? el.textContent : '') || fallback; }
        catch (err) { console.error('[content-pages] failed to parse', id, err); return fallback; }
    }

    // ─── Tiny DOM helpers ─────────────────────────────────────

    function el(tag, attrs = {}, children = []) {
        const node = document.createElement(tag);
        for (const [k, v] of Object.entries(attrs)) {
            if (v == null || v === false) continue;
            if (k === 'class') node.className = v;
            else if (k === 'text') node.textContent = v;
            else if (k === 'html') node.innerHTML = v;
            else node.setAttribute(k, v);
        }
        for (const c of [].concat(children)) {
            if (c == null) continue;
            node.appendChild(typeof c === 'string' ? document.createTextNode(c) : c);
        }
        return node;
    }

    function escapeHTML(s) {
        return String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({
            '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
        }[c]));
    }

    // ─── Toast ────────────────────────────────────────────────

    let toastTimer;
    function toast(text) {
        const wrap = $('[data-abo-admin-content-toast]');
        const txt  = $('[data-abo-admin-content-toast-text]', wrap);
        if (!wrap) return;
        txt.textContent = text;
        wrap.hidden = false;
        clearTimeout(toastTimer);
        toastTimer = setTimeout(() => { wrap.hidden = true; }, 2400);
    }

    // ─── Dirty dot ────────────────────────────────────────────

    function setDirty(d) {
        const dot = $('[data-abo-admin-content-dirty]');
        if (dot) dot.hidden = !d;
    }

    // ─── Path helpers (set / get deep fields) ─────────────────

    function getAt(obj, path) {
        return path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), obj);
    }
    function setAt(obj, path, val) {
        const parts = path.split('.');
        let cur = obj;
        for (let i = 0; i < parts.length - 1; i++) {
            if (cur[parts[i]] == null) cur[parts[i]] = {};
            cur = cur[parts[i]];
        }
        cur[parts[parts.length - 1]] = val;
    }

    // ─── Lang switch (re-usable) ──────────────────────────────

    function applyLang(lang, scope) {
        const inputs = $$('[data-abo-admin-content-field][data-abo-admin-content-lang]');
        // We only need to toggle inputs that match the current scope
        // (title / intro / content / address / success). For the
        // about page, every "field+lang" pair belongs to one block
        // scope; for the contact page, scopes are address / success.
        // The attribute we use to scope lang is the *value* of the
        // data-abo-admin-content-lang attribute on the switch button
        // (title, intro, address, success). For nested block fields
        // we'll attach the same scoping on a per-block basis.
        inputs.forEach((el) => {
            // Skip nested block fields (they manage their own lang).
            if (el.closest('[data-abo-admin-content-block-card]')) return;
            const v = el.getAttribute('data-abo-admin-content-lang');
            el.hidden = v !== lang;
        });

        // Switch buttons by scope.
        $$('[data-abo-admin-content-lang="' + scope + '"]').forEach((b) => {
            const active = b.getAttribute('data-abo-admin-content-lang-value') === lang;
            b.classList.toggle('is-active', active);
            b.setAttribute('aria-selected', active ? 'true' : 'false');
        });
    }

    function wireLangSwitches() {
        $$('[data-abo-admin-content-lang]').forEach((b) => {
            if (!b.matches('button')) return;
            b.addEventListener('click', () => {
                const scope = b.getAttribute('data-abo-admin-content-lang');
                const value = b.getAttribute('data-abo-admin-content-lang-value');
                applyLang(value, scope);
                refreshPreview();
            });
        });
    }

    // ─── Status name + status toggle ─────────────────────────

    function refreshStatusName() {
        const input = $('[data-abo-admin-content-field="status"]');
        const name  = $('[data-abo-admin-content-status-name]');
        if (!input || !name) return;
        const t = input.getAttribute('data-abo-admin-content-bool-true') || 'published';
        const f = input.getAttribute('data-abo-admin-content-bool-false') || 'draft';
        const value = input.checked ? t : f;
        name.textContent = String(value).toUpperCase();
        name.classList.toggle('abo-admin-content__status-name--draft', value === 'draft');
    }

    // ─── Char counters (SEO) ─────────────────────────────────

    function updateAllCounters() {
        $$('[data-abo-admin-content-counter-input]').forEach((el) => {
            const key  = el.getAttribute('data-abo-admin-content-counter-input');
            const max  = Number(el.getAttribute('data-abo-admin-content-counter-max') || 0);
            const out  = $('[data-abo-admin-content-counter="' + key + '"]');
            if (!out) return;
            const len = (el.value || '').length;
            out.textContent = len + ' / ' + max;
            out.classList.toggle('abo-admin-content__counter--coral', len > max);
        });
    }

    function wireCounters() {
        $$('[data-abo-admin-content-counter-input]').forEach((el) => {
            el.addEventListener('input', updateAllCounters);
        });
        updateAllCounters();
    }

    // ─── Generic field input wiring ───────────────────────────

    function wireFields(model, onChange) {
        $$('[data-abo-admin-content-field]').forEach((el) => {
            // Skip the per-block fields (they have their own wiring).
            if (el.closest('[data-abo-admin-content-block-card]')) return;
            if (el.type === 'checkbox') {
                el.addEventListener('change', () => {
                    const path = el.getAttribute('data-abo-admin-content-field');
                    if (!path) return;
                    setAt(model, path, !!el.checked);
                    setDirty(true);
                    if (path === 'status') refreshStatusName();
                    if (onChange) onChange(path, el);
                    refreshPreview();
                });
            } else {
                el.addEventListener('input', () => {
                    const path = el.getAttribute('data-abo-admin-content-field');
                    if (!path) return;
                    setAt(model, path, el.value);
                    setDirty(true);
                    if (onChange) onChange(path, el);
                    refreshPreview();
                });
            }
        });
    }

    // ─── SEO collapse ────────────────────────────────────────

    function wireSeoToggle() {
        const btn   = $('[data-abo-admin-content-seo-toggle]');
        const body  = $('[data-abo-admin-content-seo-body]');
        const text  = $('[data-abo-admin-content-seo-toggle-text]');
        if (!btn || !body) return;
        btn.addEventListener('click', () => {
            const open = btn.getAttribute('aria-expanded') === 'true';
            const next = !open;
            btn.setAttribute('aria-expanded', next ? 'true' : 'false');
            body.hidden = !next;
            if (text) text.textContent = next ? 'Hide' : 'Show';
        });
    }

    // ─── Modal helpers (close + Escape) ──────────────────────

    function wireModal(modal, onClose) {
        if (!modal) return;
        $$('[data-abo-admin-content-msg-close], [data-abo-admin-content-remove-close]', modal).forEach((b) => {
            b.addEventListener('click', () => {
                modal.hidden = true;
                if (onClose) onClose();
            });
        });
        document.addEventListener('keydown', (ev) => {
            if (modal && !modal.hidden && ev.key === 'Escape') {
                ev.preventDefault();
                modal.hidden = true;
                if (onClose) onClose();
            }
        });
    }

    // ─── Top-bar actions (Discard / Draft / Publish) ─────────

    function wireActions(onSave) {
        $$('[data-abo-admin-content-action]').forEach((b) => {
            const action = b.getAttribute('data-abo-admin-content-action');
            b.addEventListener('click', (ev) => {
                if (action === 'add-block') return; // handled by about-page code
                if (action === 'discard') {
                    if (confirm('Discard unsaved changes? This is a demo — the page will reset.')) {
                        window.location.reload();
                    }
                    return;
                }
                if (action === 'draft' || action === 'publish') {
                    ev.preventDefault();
                    if (onSave) onSave(action);
                    toast('Saved (demo)');
                }
            });
        });
    }

    // ─── Format a "last updated" date (JS) ───────────────────

    function formatDate(input) {
        const d = (input instanceof Date) ? input : new Date(input);
        if (isNaN(d.getTime())) return '—';
        const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
        const day   = String(d.getDate()).padStart(2, '0');
        const mon   = months[d.getMonth()];
        const year  = d.getFullYear();
        const hh    = String(d.getHours()).padStart(2, '0');
        const mm    = String(d.getMinutes()).padStart(2, '0');
        return day + ' ' + mon + ' ' + year + ' · ' + hh + ':' + mm;
    }

    // ─── Empty + dirty refresh ───────────────────────────────

    function refreshPreview() {
        if (typeof window.__contentRefreshPreview === 'function') {
            window.__contentRefreshPreview();
        }
    }

    // ─── Shared init (runs on both pages) ────────────────────

    function initShared() {
        wireLangSwitches();
        wireCounters();
        wireSeoToggle();
    }

    // ─── Hero image (about page only) ────────────────────────

    function wireHero(model) {
        const file   = $('[data-abo-admin-content-hero-file]');
        const thumb  = $('[data-abo-admin-content-hero-thumb]');
        const remove = $('[data-abo-admin-content-hero-remove]');
        if (!file || !thumb) return;

        // Hydrate from model.
        if (model.hero && model.hero.url) {
            thumb.style.backgroundImage = 'url("' + model.hero.url + '")';
            thumb.textContent = '';
            if (remove) remove.hidden = false;
        }

        file.addEventListener('change', () => {
            const f = file.files && file.files[0];
            if (!f) return;
            const reader = new FileReader();
            reader.onload = (ev) => {
                model.hero = { name: f.name, url: ev.target.result };
                thumb.style.backgroundImage = 'url("' + ev.target.result + '")';
                thumb.textContent = '';
                if (remove) remove.hidden = false;
                setDirty(true);
                refreshPreview();
            };
            reader.readAsDataURL(f);
        });

        if (remove) {
            remove.addEventListener('click', () => {
                model.hero = null;
                thumb.style.backgroundImage = '';
                thumb.textContent = 'HERO';
                remove.hidden = true;
                file.value = '';
                setDirty(true);
                refreshPreview();
            });
        }
    }

    // ─── ABOUT PAGE ──────────────────────────────────────────

    function initAbout(model) {
        if (!model) return;
        initShared();
        wireHero(model);

        // Block type catalogue.
        const BLOCK_TYPES = [
            { value: 'text',    label: 'Text' },
            { value: 'image',   label: 'Text + image' },
            { value: 'quote',   label: 'Quote' },
            { value: 'values',  label: 'Values list' },
        ];

        // Hydrate basic + SEO + status from model.
        $$('[data-abo-admin-content-field]').forEach((el) => {
            if (el.closest('[data-abo-admin-content-block-card]')) return;
            const path = el.getAttribute('data-abo-admin-content-field');
            if (!path) return;
            const v = getAt(model, path);
            if (el.type === 'checkbox') {
                el.checked = !!v;
            } else if (typeof v !== 'undefined') {
                el.value = v == null ? '' : v;
            }
        });
        applyLang('en', 'title');
        applyLang('en', 'intro');
        refreshStatusName();
        updateAllCounters();

        // Last updated label.
        const upEl = $('[data-abo-admin-content-updated-date]');
        if (upEl) upEl.textContent = formatDate(model.updated);
        const upSide = $('[data-abo-admin-content-updated]');
        if (upSide) upSide.textContent = formatDate(model.updated);

        // Blocks container.
        const blocksRoot   = $('[data-abo-admin-content-blocks]');
        const blocksEmpty  = $('[data-abo-admin-content-blocks-empty]');
        const blocksCount  = $('[data-abo-admin-content-blocks-count]');
        const addBlockBtn  = $('[data-abo-admin-content-action="add-block"]');

        // Per-block lang tab state.
        const blockLang = {}; // { blockId: { scope: 'en' | 'ar' } }

        function applyBlockLang(blockId, scope, lang) {
            if (!blockLang[blockId]) blockLang[blockId] = { heading: 'en', body: 'en' };
            blockLang[blockId][scope] = lang;
            const card = $('[data-abo-admin-content-block-card="' + blockId + '"]');
            if (!card) return;
            $$('[data-abo-admin-content-block-lang="' + scope + '"]', card).forEach((b) => {
                const active = b.getAttribute('data-abo-admin-content-block-lang-value') === lang;
                b.classList.toggle('is-active', active);
                b.setAttribute('aria-selected', active ? 'true' : 'false');
            });
            $$('[data-abo-admin-content-block-lang-field="' + scope + '"]', card).forEach((el) => {
                const v = el.getAttribute('data-abo-admin-content-block-lang-value');
                el.hidden = v !== lang;
            });
        }

        function renderBlocks() {
            if (!blocksRoot) return;
            blocksRoot.replaceChildren();
            const list = model.blocks || [];
            blocksCount.textContent = list.length + (list.length === 1 ? ' block' : ' blocks');
            if (blocksEmpty) blocksEmpty.hidden = list.length !== 0;

            list.forEach((block, idx) => {
                const card = el('div', {
                    class: 'abo-admin-content__block-card',
                    'data-abo-admin-content-block-card': block.id,
                });

                // Head: drag handle · type select · block number · tools
                const head = el('div', { class: 'abo-admin-content__block-card-head' });

                const handle = el('button', {
                    type: 'button',
                    class: 'abo-admin-content__block-handle',
                    'aria-label': 'Drag to reorder',
                    title: 'Drag to reorder',
                });
                handle.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M9 5h2v14H9zM13 5h2v14h-2z" fill="currentColor"/></svg>';
                head.appendChild(handle);

                const typeSel = el('select', {
                    class: 'abo-admin-content__block-type',
                    'aria-label': 'Block type',
                    'data-abo-admin-content-block-type': block.id,
                });
                BLOCK_TYPES.forEach((t) => {
                    const opt = el('option', { value: t.value, text: t.label });
                    if (t.value === block.type) opt.setAttribute('selected', 'selected');
                    typeSel.appendChild(opt);
                });
                head.appendChild(typeSel);

                head.appendChild(el('p', { class: 'abo-admin-content__block-num', text: '#' + (idx + 1) }));

                const tools = el('div', { class: 'abo-admin-content__block-tools' });
                const upBtn = el('button', {
                    type: 'button',
                    class: 'abo-admin-content__icon-btn',
                    'aria-label': 'Move up',
                    title: 'Move up',
                    'data-abo-admin-content-block-move': 'up',
                    'data-abo-admin-content-block-id': block.id,
                    disabled: idx === 0,
                });
                upBtn.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M6 14l6-6 6 6" stroke="currentColor" stroke-width="1.6" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>';
                const downBtn = el('button', {
                    type: 'button',
                    class: 'abo-admin-content__icon-btn',
                    'aria-label': 'Move down',
                    title: 'Move down',
                    'data-abo-admin-content-block-move': 'down',
                    'data-abo-admin-content-block-id': block.id,
                    disabled: idx === list.length - 1,
                });
                downBtn.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M6 10l6 6 6-6" stroke="currentColor" stroke-width="1.6" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>';
                const removeBtn = el('button', {
                    type: 'button',
                    class: 'abo-admin-content__icon-btn abo-admin-content__icon-btn--coral',
                    'aria-label': 'Remove block',
                    title: 'Remove block',
                    'data-abo-admin-content-block-remove': block.id,
                });
                removeBtn.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6 6 18" stroke="currentColor" stroke-width="1.6" fill="none" stroke-linecap="round"/></svg>';
                tools.appendChild(upBtn);
                tools.appendChild(downBtn);
                tools.appendChild(removeBtn);
                head.appendChild(tools);
                card.appendChild(head);

                // Heading (with EN/AR switch)
                const headSec = el('div', { class: 'abo-admin-content__block' });
                const headHead = el('header', { class: 'abo-admin-content__block-head' });
                headHead.appendChild(el('h3', { class: 'abo-admin-content__block-label', text: 'HEADING' }));
                const langSwitch = el('div', {
                    class: 'abo-admin-content__lang-switch',
                    role: 'tablist',
                    'aria-label': 'Block heading language',
                });
                ['en','ar'].forEach((v) => {
                    const b = el('button', {
                        type: 'button',
                        role: 'tab',
                        'aria-selected': v === 'en' ? 'true' : 'false',
                        'data-abo-admin-content-block-lang': 'heading',
                        'data-abo-admin-content-block-lang-value': v,
                    });
                    b.textContent = v.toUpperCase();
                    if (v === 'en') b.classList.add('is-active');
                    langSwitch.appendChild(b);
                });
                headHead.appendChild(langSwitch);
                headSec.appendChild(headHead);
                ['en','ar'].forEach((v) => {
                    const inp = el('input', {
                        type: 'text',
                        class: 'abo-admin-content__field-input' + (v === 'ar' ? ' abo-admin-content__field-input--rtl' : ''),
                        'aria-label': 'Block heading (' + v + ')',
                        'data-abo-admin-content-block-field': 'heading',
                        'data-abo-admin-content-block-lang-field': 'heading',
                        'data-abo-admin-content-block-lang-value': v,
                        'data-abo-admin-content-block-id': block.id,
                        value: (block.heading && block.heading[v]) || '',
                        ...(v === 'ar' ? { dir: 'rtl', lang: 'ar' } : {}),
                    });
                    if (v === 'ar') inp.hidden = true;
                    headSec.appendChild(inp);
                });
                card.appendChild(headSec);

                // Body toolbar + contenteditable
                const bodySec = el('div', { class: 'abo-admin-content__block' });
                const bodyHead = el('header', { class: 'abo-admin-content__block-head' });
                bodyHead.appendChild(el('h3', { class: 'abo-admin-content__block-label', text: 'BODY' }));
                const langSwitch2 = el('div', {
                    class: 'abo-admin-content__lang-switch',
                    role: 'tablist',
                    'aria-label': 'Block body language',
                });
                ['en','ar'].forEach((v) => {
                    const b = el('button', {
                        type: 'button',
                        role: 'tab',
                        'aria-selected': v === 'en' ? 'true' : 'false',
                        'data-abo-admin-content-block-lang': 'body',
                        'data-abo-admin-content-block-lang-value': v,
                    });
                    b.textContent = v.toUpperCase();
                    if (v === 'en') b.classList.add('is-active');
                    langSwitch2.appendChild(b);
                });
                bodyHead.appendChild(langSwitch2);
                bodySec.appendChild(bodyHead);

                const tb = el('div', {
                    class: 'abo-admin-content__toolbar-strip',
                    role: 'toolbar',
                    'aria-label': 'Formatting',
                });
                const tbBtns = [
                    { k: 'bold',                 label: 'Bold' },
                    { k: 'italic',               label: 'Italic' },
                    { k: 'formatBlock',          label: 'H2',  arg: 'H2' },
                    { k: 'formatBlock',          label: 'H3',  arg: 'H3' },
                    { k: 'insertUnorderedList',  label: 'Bullet list' },
                    { k: 'createLink',           label: 'Link' },
                ];
                tbBtns.forEach((b) => {
                    const btn = el('button', {
                        type: 'button',
                        class: 'abo-admin-content__tb-btn',
                        'data-abo-admin-content-block-tb': b.k,
                        'aria-label': b.label,
                    });
                    if (b.arg) btn.setAttribute('data-abo-admin-content-block-tb-arg', b.arg);
                    if (b.k === 'bold') btn.innerHTML = '<strong>B</strong>';
                    else if (b.k === 'italic') btn.innerHTML = '<em>I</em>';
                    else btn.textContent = b.label;
                    tb.appendChild(btn);
                });
                bodySec.appendChild(tb);

                ['en','ar'].forEach((v) => {
                    const div = el('div', {
                        class: 'abo-admin-content__content' + (v === 'ar' ? ' abo-admin-content__content--rtl' : ''),
                        contenteditable: 'true',
                        role: 'textbox',
                        'aria-multiline': 'true',
                        'aria-label': 'Block body (' + v + ')',
                        'data-abo-admin-content-block-field': 'body',
                        'data-abo-admin-content-block-lang-field': 'body',
                        'data-abo-admin-content-block-lang-value': v,
                        'data-abo-admin-content-block-id': block.id,
                        ...(v === 'ar' ? { dir: 'rtl', lang: 'ar' } : {}),
                    });
                    div.innerHTML = (block.body && block.body[v]) || '';
                    if (v === 'ar') div.hidden = true;
                    bodySec.appendChild(div);
                });
                card.appendChild(bodySec);

                // Optional image (only visible when type = image or
                // show unconditionally with a hint; we keep it always
                // visible but light).
                const imgSec = el('div', { class: 'abo-admin-content__block' });
                imgSec.appendChild(el('h3', { class: 'abo-admin-content__block-label', text: 'IMAGE (OPTIONAL)' }));
                const imgRow = el('div', { class: 'abo-admin-content__image' });
                const imgThumb = el('span', {
                    class: 'abo-admin-content__image-thumb',
                    'aria-hidden': 'true',
                    'data-abo-admin-content-block-image-thumb': block.id,
                });
                if (block.image && block.image.url) {
                    imgThumb.style.backgroundImage = 'url("' + block.image.url + '")';
                    imgThumb.textContent = '';
                } else {
                    imgThumb.textContent = 'IMG';
                }
                const imgActions = el('div', { class: 'abo-admin-content__image-actions' });
                const imgLabel = el('label', {
                    for: 'abo-admin-content-block-image-' + block.id,
                    text: (block.image && block.image.name) || 'No image selected',
                });
                const imgHint = el('small', { text: 'Pick a file from your computer. Local preview only.' });
                const imgInput = el('input', {
                    type: 'file',
                    id: 'abo-admin-content-block-image-' + block.id,
                    class: 'abo-admin-content__file',
                    accept: 'image/*',
                    'data-abo-admin-content-block-image-input': block.id,
                });
                imgActions.appendChild(imgLabel);
                imgActions.appendChild(imgHint);
                imgActions.appendChild(imgInput);
                imgRow.appendChild(imgThumb);
                imgRow.appendChild(imgActions);
                const imgRemove = el('button', {
                    type: 'button',
                    class: 'abo-admin-content__image-remove',
                    'data-abo-admin-content-block-image-remove': block.id,
                });
                if (!block.image) imgRemove.hidden = true;
                imgRemove.textContent = 'REMOVE';
                imgRow.appendChild(imgRemove);
                imgSec.appendChild(imgRow);
                card.appendChild(imgSec);

                blocksRoot.appendChild(card);

                // Initial lang state.
                applyBlockLang(block.id, 'heading', 'en');
                applyBlockLang(block.id, 'body', 'en');
            });
        }

        function renderPreview() {
            const tEl  = $('[data-abo-admin-content-preview-title]');
            const hero = $('[data-abo-admin-content-preview-hero]');
            const introEl = $('[data-abo-admin-content-preview-intro]');
            const blocksEl = $('[data-abo-admin-content-preview-blocks]');
            if (tEl)   tEl.textContent = (model.title && model.title.en) || '—';
            if (introEl) introEl.textContent = (model.intro && model.intro.en) || '';
            if (hero) {
                if (model.hero && model.hero.url) {
                    hero.style.backgroundImage = 'url("' + model.hero.url + '")';
                    hero.textContent = '';
                } else {
                    hero.style.backgroundImage = '';
                    hero.textContent = 'HERO';
                }
            }
            if (blocksEl) {
                blocksEl.replaceChildren();
                (model.blocks || []).forEach((b) => {
                    const wrap = el('div', { class: 'abo-admin-content__preview-block' });
                    const lbl  = el('p', { class: 'abo-admin-content__preview-block-label', text: (b.type || 'text').toUpperCase() });
                    const t    = el('p', { class: 'abo-admin-content__preview-block-title', text: (b.heading && b.heading.en) || 'Untitled block' });
                    wrap.appendChild(lbl);
                    wrap.appendChild(t);
                    blocksEl.appendChild(wrap);
                });
            }
        }
        window.__contentRefreshPreview = renderPreview;

        // Wire block list events (delegated).
        function wireBlocks() {
            if (!blocksRoot) return;
            blocksRoot.addEventListener('click', (ev) => {
                const langBtn = ev.target.closest('[data-abo-admin-content-block-lang]');
                if (langBtn) {
                    const scope = langBtn.getAttribute('data-abo-admin-content-block-lang');
                    const value = langBtn.getAttribute('data-abo-admin-content-block-lang-value');
                    const card  = langBtn.closest('[data-abo-admin-content-block-card]');
                    if (card) applyBlockLang(card.getAttribute('data-abo-admin-content-block-card'), scope, value);
                    return;
                }
                const up = ev.target.closest('[data-abo-admin-content-block-move="up"]');
                if (up) {
                    const id = up.getAttribute('data-abo-admin-content-block-id');
                    moveBlock(id, -1);
                    return;
                }
                const down = ev.target.closest('[data-abo-admin-content-block-move="down"]');
                if (down) {
                    const id = down.getAttribute('data-abo-admin-content-block-id');
                    moveBlock(id, +1);
                    return;
                }
                const rm = ev.target.closest('[data-abo-admin-content-block-remove]');
                if (rm) {
                    const id = rm.getAttribute('data-abo-admin-content-block-remove');
                    requestRemoveBlock(id);
                    return;
                }
                // Toolbar buttons
                const tb = ev.target.closest('[data-abo-admin-content-block-tb]');
                if (tb) {
                    ev.preventDefault();
                    const card = tb.closest('[data-abo-admin-content-block-card]');
                    if (!card) return;
                    const blockId = card.getAttribute('data-abo-admin-content-block-card');
                    const scope   = 'body';
                    const lang    = (blockLang[blockId] && blockLang[blockId][scope]) || 'en';
                    const bodyEl  = card.querySelector('[data-abo-admin-content-block-field="body"][data-abo-admin-content-block-lang-value="' + lang + '"]');
                    if (bodyEl) bodyEl.focus();
                    const cmd = tb.getAttribute('data-abo-admin-content-block-tb');
                    const arg = tb.getAttribute('data-abo-admin-content-block-tb-arg');
                    if (cmd === 'createLink') {
                        const url = prompt('Link URL (https://…)');
                        if (!url) return;
                        document.execCommand('createLink', false, url);
                    } else if (cmd === 'formatBlock' && arg) {
                        document.execCommand('formatBlock', false, arg);
                    } else {
                        document.execCommand(cmd, false, null);
                    }
                    // Sync model.
                    const block = (model.blocks || []).find((b) => b.id === blockId);
                    if (block) {
                        if (!block.body) block.body = { en: '', ar: '' };
                        block.body[lang] = bodyEl ? bodyEl.innerHTML : '';
                        setDirty(true);
                        renderPreview();
                    }
                }
            });

            blocksRoot.addEventListener('input', (ev) => {
                const target = ev.target;
                if (!target.matches('[data-abo-admin-content-block-field]')) return;
                const id   = target.getAttribute('data-abo-admin-content-block-id');
                const fld  = target.getAttribute('data-abo-admin-content-block-field');
                const lang = target.getAttribute('data-abo-admin-content-block-lang-value');
                const block = (model.blocks || []).find((b) => b.id === id);
                if (!block) return;
                if (fld === 'heading') {
                    if (!block.heading) block.heading = { en: '', ar: '' };
                    block.heading[lang] = target.value;
                } else if (fld === 'body') {
                    if (!block.body) block.body = { en: '', ar: '' };
                    block.body[lang] = target.innerHTML;
                }
                setDirty(true);
                renderPreview();
            });

            blocksRoot.addEventListener('change', (ev) => {
                const target = ev.target;
                if (target.matches('[data-abo-admin-content-block-type]')) {
                    const id = target.getAttribute('data-abo-admin-content-block-type');
                    const block = (model.blocks || []).find((b) => b.id === id);
                    if (block) {
                        block.type = target.value;
                        setDirty(true);
                        renderPreview();
                    }
                    return;
                }
                if (target.matches('[data-abo-admin-content-block-image-input]')) {
                    const id  = target.getAttribute('data-abo-admin-content-block-image-input');
                    const f   = target.files && target.files[0];
                    if (!f) return;
                    const reader = new FileReader();
                    reader.onload = (e) => {
                        const block = (model.blocks || []).find((b) => b.id === id);
                        if (!block) return;
                        block.image = { name: f.name, url: e.target.result };
                        const thumb = $('[data-abo-admin-content-block-image-thumb="' + id + '"]');
                        if (thumb) {
                            thumb.style.backgroundImage = 'url("' + e.target.result + '")';
                            thumb.textContent = '';
                        }
                        const rm = $('[data-abo-admin-content-block-image-remove="' + id + '"]');
                        if (rm) rm.hidden = false;
                        const lbl = target.previousElementSibling;
                        if (lbl) lbl.textContent = f.name;
                        setDirty(true);
                    };
                    reader.readAsDataURL(f);
                }
            });

            blocksRoot.addEventListener('click', (ev) => {
                const rm = ev.target.closest('[data-abo-admin-content-block-image-remove]');
                if (rm) {
                    const id = rm.getAttribute('data-abo-admin-content-block-image-remove');
                    const block = (model.blocks || []).find((b) => b.id === id);
                    if (block) {
                        block.image = null;
                        const thumb = $('[data-abo-admin-content-block-image-thumb="' + id + '"]');
                        if (thumb) {
                            thumb.style.backgroundImage = '';
                            thumb.textContent = 'IMG';
                        }
                        const inp = $('[data-abo-admin-content-block-image-input="' + id + '"]');
                        if (inp) inp.value = '';
                        const lbl = inp ? inp.previousElementSibling : null;
                        if (lbl) lbl.textContent = 'No image selected';
                        rm.hidden = true;
                        setDirty(true);
                    }
                }
            });
        }

        function moveBlock(id, dir) {
            const list = model.blocks || (model.blocks = []);
            const idx = list.findIndex((b) => b.id === id);
            if (idx < 0) return;
            const next = idx + dir;
            if (next < 0 || next >= list.length) return;
            const [item] = list.splice(idx, 1);
            list.splice(next, 0, item);
            renderBlocks();
            renderPreview();
            setDirty(true);
        }

        // Block remove confirm modal.
        const removeModal  = $('[data-abo-admin-content-remove]');
        const removeBody   = $('[data-abo-admin-content-remove-body]');
        const removeConfirm= $('[data-abo-admin-content-remove-confirm]');
        let pendingRemoveId = null;
        function requestRemoveBlock(id) {
            const block = (model.blocks || []).find((b) => b.id === id);
            if (!block || !removeModal) return;
            pendingRemoveId = id;
            if (removeBody) {
                const name = (block.heading && (block.heading.en || block.heading.ar)) || 'this block';
                removeBody.textContent = '"' + name + '" will be removed from the page. This action cannot be undone.';
            }
            removeModal.hidden = false;
            setTimeout(() => {
                const cancel = removeModal.querySelector('[data-abo-admin-content-remove-close]');
                if (cancel) cancel.focus();
            }, 30);
        }
        if (removeConfirm) {
            removeConfirm.addEventListener('click', () => {
                if (!pendingRemoveId) return;
                const idx = (model.blocks || []).findIndex((b) => b.id === pendingRemoveId);
                if (idx >= 0) model.blocks.splice(idx, 1);
                pendingRemoveId = null;
                removeModal.hidden = true;
                renderBlocks();
                renderPreview();
                setDirty(true);
            });
        }
        wireModal(removeModal);

        // Add block.
        if (addBlockBtn) {
            addBlockBtn.addEventListener('click', () => {
                if (!model.blocks) model.blocks = [];
                const id = 'b-' + Date.now();
                model.blocks.push({
                    id,
                    type: 'text',
                    heading: { en: 'New block', ar: 'بلوك جديد' },
                    body:    { en: '<p>Start writing here…</p>', ar: '<p>ابدأ الكتابة هنا…</p>' },
                    image:   null,
                });
                renderBlocks();
                renderPreview();
                setDirty(true);
                // Focus the first heading input of the new block.
                setTimeout(() => {
                    const inp = $('[data-abo-admin-content-block-card="' + id + '"] [data-abo-admin-content-block-field="heading"]');
                    if (inp) inp.focus();
                }, 30);
            });
        }

        // Wire basic + SEO + status.
        wireFields(model, (path) => {
            // Refresh status label when checkbox toggles.
            if (path === 'status') refreshStatusName();
        });

        // Wire top actions.
        wireActions(() => {
            model.updated = new Date().toISOString();
            const upEl = $('[data-abo-admin-content-updated-date]');
            if (upEl) upEl.textContent = formatDate(model.updated);
            const upSide = $('[data-abo-admin-content-updated]');
            if (upSide) upSide.textContent = formatDate(model.updated);
            setDirty(false);
        });

        renderBlocks();
        renderPreview();
        wireBlocks();
    }

    // ─── CONTACT PAGE ────────────────────────────────────────

    function initContact(model) {
        if (!model) return;
        initShared();

        // Hydrate detail / form / SEO / status from model.
        $$('[data-abo-admin-content-field]').forEach((el) => {
            const path = el.getAttribute('data-abo-admin-content-field');
            if (!path) return;
            const v = getAt(model, path);
            if (el.type === 'checkbox') {
                el.checked = !!v;
            } else if (typeof v !== 'undefined') {
                el.value = v == null ? '' : v;
            }
        });
        applyLang('en', 'address');
        applyLang('en', 'success');
        refreshStatusName();
        updateAllCounters();

        // Working hours (7 rows).
        const hoursRoot = $('[data-abo-admin-content-hours]');
        const DAYS = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];

        function renderHours() {
            if (!hoursRoot) return;
            hoursRoot.replaceChildren();
            (model.hours || []).forEach((row) => {
                const r = el('div', { class: 'abo-admin-content__hours-row' });
                r.appendChild(el('p', {
                    class: 'abo-admin-content__hours-day',
                    'data-abo-admin-content-hours-day': row.day,
                    text: row.day.slice(0, 3).toUpperCase(),
                }));
                const open = el('input', {
                    type: 'time',
                    class: 'abo-admin-content__hours-time',
                    'aria-label': row.day + ' open time',
                    'data-abo-admin-content-hours-field': 'open',
                    'data-abo-admin-content-hours-day': row.day,
                    value: row.open || '',
                });
                r.appendChild(open);
                r.appendChild(el('span', { class: 'abo-admin-content__hours-sep', text: '—' }));
                const close = el('input', {
                    type: 'time',
                    class: 'abo-admin-content__hours-time',
                    'aria-label': row.day + ' close time',
                    'data-abo-admin-content-hours-field': 'close',
                    'data-abo-admin-content-hours-day': row.day,
                    value: row.close || '',
                });
                r.appendChild(close);
                const closedLabel = el('label', { class: 'abo-admin-content__switch', style: 'margin-left:.2rem' });
                const closedInp = el('input', {
                    type: 'checkbox',
                    'data-abo-admin-content-hours-closed': row.day,
                });
                if (row.closed) closedInp.setAttribute('checked', 'checked');
                closedLabel.appendChild(closedInp);
                const track = el('span', { class: 'abo-admin-content__switch-track', 'aria-hidden': 'true' });
                const thumb = el('span', { class: 'abo-admin-content__switch-thumb' });
                track.appendChild(thumb);
                closedLabel.appendChild(track);
                // Inline label.
                const closedText = el('span', {
                    text: 'Closed',
                    style: 'margin-left:.4rem;color:var(--abo-admin-gray);font-size:0.7rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase',
                });
                closedLabel.appendChild(closedText);
                r.appendChild(closedLabel);
                // Initial disabled state.
                if (row.closed) {
                    open.disabled = true;
                    close.disabled = true;
                }
                hoursRoot.appendChild(r);
            });
        }

        function wireHours() {
            if (!hoursRoot) return;
            hoursRoot.addEventListener('change', (ev) => {
                const target = ev.target;
                if (target.matches('[data-abo-admin-content-hours-closed]')) {
                    const day = target.getAttribute('data-abo-admin-content-hours-closed');
                    const row = (model.hours || []).find((r) => r.day === day);
                    if (!row) return;
                    row.closed = target.checked;
                    const open  = hoursRoot.querySelector('[data-abo-admin-content-hours-field="open"][data-abo-admin-content-hours-day="' + day + '"]');
                    const close = hoursRoot.querySelector('[data-abo-admin-content-hours-field="close"][data-abo-admin-content-hours-day="' + day + '"]');
                    if (open)  open.disabled  = row.closed;
                    if (close) close.disabled = row.closed;
                    setDirty(true);
                    renderPreview();
                    return;
                }
                if (target.matches('[data-abo-admin-content-hours-field]')) {
                    const day = target.getAttribute('data-abo-admin-content-hours-day');
                    const fld = target.getAttribute('data-abo-admin-content-hours-field');
                    const row = (model.hours || []).find((r) => r.day === day);
                    if (!row) return;
                    row[fld] = target.value;
                    setDirty(true);
                    renderPreview();
                }
            });
        }

        // Messages inbox.
        const messagesRoot  = $('[data-abo-admin-content-messages]');
        const messagesEmpty = $('[data-abo-admin-content-messages-empty]');
        const messagesCount = $('[data-abo-admin-content-messages-count]');

        function renderMessages() {
            if (!messagesRoot) return;
            const list = model.messages || [];
            messagesCount.textContent = list.length + (list.length === 1 ? ' message' : ' messages');
            if (messagesEmpty) messagesEmpty.hidden = list.length !== 0;
            if (list.length === 0) {
                messagesRoot.replaceChildren();
                return;
            }
            const tbl = el('table', { class: 'abo-admin-content__inbox-table', role: 'table' });
            const thead = el('thead', {}, el('tr', {}, [
                el('th', { text: 'Name' }),
                el('th', { text: 'Subject' }),
                el('th', { text: 'Date' }),
                el('th', { text: 'Status' }),
            ]));
            tbl.appendChild(thead);
            const tbody = el('tbody');
            list.forEach((m) => {
                const tr = el('tr', {
                    'data-abo-admin-content-message': m.id,
                    tabindex: '0',
                    role: 'button',
                    'aria-label': 'Open message from ' + m.name,
                });
                tr.appendChild(el('td', { text: m.name }));
                tr.appendChild(el('td', { text: m.subject }));
                tr.appendChild(el('td', { text: formatDate(m.date) }));
                const pillCls = m.status === 'new' ? 'abo-admin-content__pill--new' : 'abo-admin-content__pill--replied';
                tr.appendChild(el('td', {}, el('span', { class: 'abo-admin-content__pill ' + pillCls, text: m.status })));
                tbody.appendChild(tr);
            });
            tbl.appendChild(tbody);
            messagesRoot.replaceChildren(tbl);
        }

        // Message modal.
        const msgModal    = $('[data-abo-admin-content-msg]');
        const msgMeta     = $('[data-abo-admin-content-msg-meta]');
        const msgBody     = $('[data-abo-admin-content-msg-body]');
        const msgReplied  = $('[data-abo-admin-content-msg-replied]');
        const msgTitle    = $('[data-abo-admin-content-msg-title]');
        let activeMsgId = null;

        function openMessage(id) {
            const m = (model.messages || []).find((x) => x.id === id);
            if (!m || !msgModal) return;
            activeMsgId = id;
            if (msgTitle) msgTitle.textContent = m.subject || 'MESSAGE';
            if (msgMeta) {
                msgMeta.replaceChildren();
                const rows = [
                    ['Name',   m.name],
                    ['Email',  m.email],
                    ['Date',   formatDate(m.date)],
                    ['Status', m.status.toUpperCase()],
                ];
                rows.forEach(([k, v]) => {
                    msgMeta.appendChild(el('dt', { text: k }));
                    msgMeta.appendChild(el('dd', { text: v }));
                });
            }
            if (msgBody) msgBody.textContent = m.body || '';
            msgModal.hidden = false;
            setTimeout(() => {
                const close = msgModal.querySelector('[data-abo-admin-content-msg-close]');
                if (close) close.focus();
            }, 30);
        }

        function wireMessages() {
            if (!messagesRoot) return;
            messagesRoot.addEventListener('click', (ev) => {
                const tr = ev.target.closest('[data-abo-admin-content-message]');
                if (!tr) return;
                openMessage(tr.getAttribute('data-abo-admin-content-message'));
            });
            messagesRoot.addEventListener('keydown', (ev) => {
                if (ev.key !== 'Enter' && ev.key !== ' ') return;
                const tr = ev.target.closest('[data-abo-admin-content-message]');
                if (!tr) return;
                ev.preventDefault();
                openMessage(tr.getAttribute('data-abo-admin-content-message'));
            });
        }

        if (msgReplied) {
            msgReplied.addEventListener('click', () => {
                if (!activeMsgId) return;
                const m = (model.messages || []).find((x) => x.id === activeMsgId);
                if (m) {
                    m.status = 'replied';
                    renderMessages();
                    setDirty(true);
                }
                if (msgModal) msgModal.hidden = true;
            });
        }
        wireModal(msgModal);

        // Live preview.
        function renderPreview() {
            const phoneEl   = $('[data-abo-admin-content-preview-phone]');
            const emailEl   = $('[data-abo-admin-content-preview-email]');
            const addressEl = $('[data-abo-admin-content-preview-address]');
            const todayEl   = $('[data-abo-admin-content-preview-today]');
            const d = (model.details) || {};
            if (phoneEl)   phoneEl.textContent   = d.phone || '—';
            if (emailEl)   emailEl.textContent   = d.email || '—';
            if (addressEl) addressEl.textContent = (d.address && d.address.en) ? d.address.en : '—';
            // Today's hours — based on JS Date now (browser locale).
            const now = new Date();
            const dayIndex = now.getDay(); // 0=Sun ... 6=Sat
            const today = (model.hours || [])[dayIndex];
            if (todayEl) {
                if (!today) {
                    todayEl.textContent = '—';
                } else if (today.closed) {
                    todayEl.textContent = 'Closed today';
                } else {
                    todayEl.textContent = (today.open || '—') + ' – ' + (today.close || '—');
                }
            }
        }
        window.__contentRefreshPreview = renderPreview;

        // Wire generic fields (basic + form settings + status).
        wireFields(model);

        // Wire top actions.
        wireActions(() => { setDirty(false); });

        renderHours();
        wireHours();
        renderMessages();
        wireMessages();
        renderPreview();
    }

    // ─── Boot ────────────────────────────────────────────────

    function boot() {
        const about   = readJSON('abo-admin-content-about-data', null);
        const contact = readJSON('abo-admin-content-contact-data', null);
        if (about)   initAbout(about);
        if (contact) initContact(contact);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', boot);
    } else {
        boot();
    }
})();
